UPDATE merchant_store_profile
SET intro=#{intro},announcement=#{announcement},business_hours=#{businessHours},promo_level=#{promoLevel},
    promo_title=#{promoTitle},promo_text=#{promoText},photo_asset_ids=#{photoAssetIds},
    version=version+1,updated_at=#{now}
WHERE store_id=#{storeId} AND merchant_id=#{merchantId} AND version=#{expectedVersion}
